fn start_benchmark_campaign(&mut self) -> Result<(), String> {
    let manual_run_active = self.active_run_id.as_deref().is_some_and(|run_id| {
        self.host.run(run_id).is_ok_and(|run| {
            !matches!(
                run.state,
                AgentRunState::Completed | AgentRunState::Failed | AgentRunState::Cancelled
            )
        })
    });
    if manual_run_active
        || self.native_question.is_some()
        || self.process.is_some()
        || self.model_resource_task.is_some()
    {
        return Err(
            "Finish or stop current AI Studio inference/runtime work before starting a measured campaign."
                .to_owned(),
        );
    }
    let verified = self.benchmark_campaign_verified_models()?;
